def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([1, 1, 1]), fmt([2, 3, 8, 9]), fmt([1, 4, 6, 9, 10]), fmt([10, 1, 1]), fmt([1, 10**9]), fmt([1, 2]), fmt([10**9, 10**9, 1])]
    for n in (2, 3, 4, 5, 7, 10, 15, 25):
        for _ in range(3):
            hi = rng.choice([3, 10, 50, 1000])
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)]))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(100000)]))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(99999)]))
    tests.append(fmt([10**9 - rng.randint(0, 3) for _ in range(100000)]))
    tests.append(fmt([rng.randint(1, 5) for _ in range(100000)]))
    return tests
